import{_ as e,o as t,c as i,a4 as a}from"./chunks/framework.BE47AOxC.js";const c=JSON.parse('{"title":"Versions","description":"Versions publiées de Teuthis-CMS, leurs notes et la vérification des signatures des images.","frontmatter":{"title":"Versions","description":"Versions publiées de Teuthis-CMS, leurs notes et la vérification des signatures des images."},"headers":[],"relativePath":"versions/index.md","filePath":"versions/index.md"}'),r={name:"versions/index.md"};function n(o,s,d,l,h,p){return t(),i("div",null,[...s[0]||(s[0]=[a(`<h1 id="versions" tabindex="-1">Versions <a class="header-anchor" href="#versions" aria-label="Permalink to &quot;Versions&quot;">​</a></h1><p>Cette documentation est celle de la <strong>dernière version publiée</strong> (v0.8.0 au moment de sa construction) : elle est reconstruite à chaque nouvelle étiquette, et il n&#39;y a pas de documentation par version. Les notes de chaque version gardent l&#39;historique de ce qui change et de ce que l&#39;exploitant doit faire en mettant à jour.</p><h2 id="versions-publiees" tabindex="-1">Les versions publiées <a class="header-anchor" href="#versions-publiees" aria-label="Permalink to &quot;Les versions publiées {#versions-publiees}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Version</th><th>Publiée le</th><th>Notes</th></tr></thead><tbody><tr><td><strong>v0.8.0</strong></td><td>9 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-8-0">Lire les notes</a></td></tr><tr><td><strong>v0.7.1</strong></td><td>8 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-7-1">Lire les notes</a></td></tr><tr><td><strong>v0.7.0</strong></td><td>8 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-7-0">Lire les notes</a></td></tr><tr><td><strong>v0.6.0</strong></td><td>8 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-6-0">Lire les notes</a></td></tr><tr><td><strong>v0.5.0</strong></td><td>7 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-5-0">Lire les notes</a></td></tr><tr><td><strong>v0.4.0</strong></td><td>7 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-4-0">Lire les notes</a></td></tr><tr><td><strong>v0.3.1</strong></td><td>2 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-3-1">Lire les notes</a></td></tr><tr><td><strong>v0.3.0</strong></td><td>2 octobre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-3-0">Lire les notes</a></td></tr><tr><td><strong>v0.2.1</strong></td><td>30 septembre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-2-1">Lire les notes</a></td></tr><tr><td><strong>v0.2.0</strong></td><td>30 septembre 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-2-0">Lire les notes</a></td></tr><tr><td><strong>v0.1.0</strong></td><td>28 août 2026</td><td><a href="/teuthis-cms-distribution/versions/v0-1-0">Lire les notes</a></td></tr><tr><td><strong>v1.1.0</strong></td><td>20 août 2026</td><td><a href="/teuthis-cms-distribution/versions/v1-1-0">Lire les notes</a></td></tr></tbody></table><p>Les fichiers de chaque version (installateur, archive de la pile et leurs sommes SHA-256) sont sur la <a href="https://github.com/Bastien-OC20/teuthis-cms-distribution/releases" target="_blank" rel="noreferrer">page des releases</a>.</p><h2 id="verifier-les-signatures" tabindex="-1">Vérifier les signatures des images <a class="header-anchor" href="#verifier-les-signatures" aria-label="Permalink to &quot;Vérifier les signatures des images {#verifier-les-signatures}&quot;">​</a></h2><p>Chaque image de production (<code>teuthis-api</code>, <code>teuthis-admin</code>, <code>teuthis-front</code>) est publiée sur <code>ghcr.io/bastien-oc20/</code>, <strong>signée sans clé</strong> par <a href="https://docs.sigstore.dev/" target="_blank" rel="noreferrer">cosign</a> depuis le workflow de publication, et sa signature se vérifie sans rien demander à personne. La signature prouve que l&#39;image vient du workflow <code>publication-images.yml</code> du dépôt du code, pour <strong>cette version exacte</strong> et pas une autre. Il faut cosign <strong>v3 ou plus récent</strong> : les images sont signées au format de cosign v3, que les versions précédentes ne lisent pas (voir les <a href="https://docs.sigstore.dev/cosign/system_config/installation/" target="_blank" rel="noreferrer">instructions d&#39;installation de cosign</a>).</p><p>L&#39;installateur fait cette vérification lui-même quand cosign est présent sur le serveur (voir <a href="/teuthis-cms-distribution/installer/guide-pas-a-pas#lauthenticité-des-images">L&#39;authenticité des images</a>). Pour la faire à la main :</p><p><strong>1. Lire l&#39;empreinte de chaque image</strong> dans l&#39;archive de la pile de la version, après avoir vérifié la somme de l&#39;archive :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">curl</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -fsSLO</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> https://github.com/Bastien-OC20/teuthis-cms-distribution/releases/download/vX.Y.Z/teuthis-deploy-X.Y.Z.tar.gz</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">curl</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -fsSLO</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> https://github.com/Bastien-OC20/teuthis-cms-distribution/releases/download/vX.Y.Z/teuthis-deploy-X.Y.Z.tar.gz.sha256</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">sha256sum</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -c</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis-deploy-X.Y.Z.tar.gz.sha256</span></span>
<span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">tar</span><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;"> -xzOf</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis-deploy-X.Y.Z.tar.gz</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> teuthis-deploy-X.Y.Z/images-publiees.txt</span></span></code></pre></div><p>Chaque ligne affichée est de la forme <code>image:X.Y.Z@sha256:…</code>.</p><p><strong>2. Vérifier la signature</strong> d&#39;une image par son empreinte, jamais par son étiquette (une étiquette peut en théorie être republiée sur une autre empreinte) :</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-high-contrast github-dark-high-contrast vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#702C00;--shiki-dark:#FFB757;">cosign</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> verify</span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;">  --certificate-identity-regexp</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> &#39;^https://github\\.com/Bastien-OC20/calamars/\\.github/workflows/publication-images\\.yml@refs/tags/vX\\.Y\\.Z$&#39;</span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;"> \\</span></span>
<span class="line"><span style="--shiki-light:#023B95;--shiki-dark:#91CBFF;">  --certificate-oidc-issuer</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;"> https://token.actions.githubusercontent.com</span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">  ghcr.io/bastien-oc20/teuthis-api@sha256:</span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;">&lt;</span><span style="--shiki-light:#032563;--shiki-dark:#ADDCFF;">empreint</span><span style="--shiki-light:#0E1116;--shiki-dark:#F0F3F6;">e</span><span style="--shiki-light:#A0111F;--shiki-dark:#FF9492;">&gt;</span></span></code></pre></div><p>Remplacez <code>X.Y.Z</code> par la version (dans l&#39;expression, les points sont échappés : <code>X\\.Y\\.Z</code>) et <code>&lt;empreinte&gt;</code> par celle de l&#39;image lue à l&#39;étape 1. Répétez pour <code>teuthis-admin</code> et <code>teuthis-front</code>.</p><p><code>cosign verify</code> échoue si l&#39;image a été reconstruite ou republiée par un autre workflow, ou sur une autre étiquette de version : dans ce cas, <strong>ne la déployez pas</strong>.</p>`,15)])])}const g=e(r,[["render",n]]);export{c as __pageData,g as default};
